<?php
require_once(__DIR__.'/../../../init.php'); require_once(__DIR__.'/dictionary.php'); require_once(__DIR__.'/table.php'); require_once(__DIR__.'/dataSet.php'); require_once(__DIR__.'/calculator.php'); require_once(__DIR__.'/import.php'); require_once(__DIR__.'/print.php'); class Engine { public static $db; public static $setId; public static $params; public static $mainId; public static $returnDataSets; public static $returnTables; public static $isBatch = false; public static function begin ($params) { self::$db = connectDb(); self::$setId = (int) getSessionValue('mapGenTableSetCode'); self::$params = $params; self::$mainId = $params->dataSetId = isset($params->dataSetId) && $params->isReport ? $params->dataSetId : 0; self::$db->beginTransaction(); Dictionary::load(); } public static function end () { self::$db->commit(); } public static function load ($params, $noCleanup = false) { self::begin($params); $result = new stdClass; $dataSet = DataSet::get($params->dataSetId, isset($params->recalculate) ? $params->recalculate : false); $table = $dataSet->table; $result->changed = DataSet::$changedDataSets; $result->dataSetId = $dataSet->id; $result->dictionaries = Dictionary::$dictionaries; if ($noCleanup) { $result->dictionariesAllItems = Dictionary::$allItems; } if ($params->isReport) { self::$returnDataSets[$dataSet->id] = $dataSet; self::$returnTables[$table->id] = $table; if ($noCleanup) { $result->dataSets = self::$returnDataSets; $result->tables = self::$returnTables; } else { $result->dataSets = DataSet::cleanupDataSets(self::$returnDataSets); $result->tables = Table::cleanupTables(self::$returnTables); } } else { if ($noCleanup) { $result->dataSets = [$dataSet->id => $dataSet]; $result->tables = [$table->id => $table]; } else { $result->dataSets = [$dataSet->id => $dataSet->getCleaned()]; $result->tables = [$table->id => $table->cleanup()]; } } self::end(); return $result; } public static function save ($params) { self::begin($params); $result = new stdClass; $params->userId = getSessionValue('user'); DataSet::save($params); $result->changed = DataSet::$changedDataSets; self::end(); return $result; } public static function delete ($dataSetId) { $params = new stdClass; $params->isReport = true; self::begin($params); $result = new stdClass; DataSet::delete($dataSetId); $result->changed = DataSet::$changedDataSets; self::end(); return $result; } public static function import ($params) { self::begin($params); if (!$params->dataSetId) { $dataSet = DataSet::get(0, false)->getCleaned(); DataSet::save($dataSet); $params->dataSetId = $dataSet->id; } (new Import)->convert(); DataSet::restart(); DataSet::get($params->dataSetId, true); $result = new stdClass; $result->changed = DataSet::$changedDataSets; $result->dataSetId = $params->dataSetId; self::end(); return $result; } } 